# POST /api/sheets/{sheetId}/bulk-retire — retire the selected people together from a date (blank: the sheet's today).
# A date that is not yyyy-MM-dd is a 400 and writes nothing. Each selected person on the sheet, in list order (see the
# people's move), is retired exactly as the row's retire would (see RetirePeople): PERSON_RETIRED and the figures it
# moved. Responds with how many were retired.
validate:
  class: net.officefloor.hq.app.person.ValidateBulkRetire
  next: retire
retire:
  class: net.officefloor.hq.app.person.RetirePeople
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithBulkRetire
# POST /api/sheets/{sheetId}/people/{personId}/hold — add a hold on a person from a date (blank: the sheet's today) until
# an optional to-date; a person may have several holds over time. A date that is not yyyy-MM-dd, or a to-date before the
# from-date, is a 400 and a person not on the sheet a 404, none writing anything. Only the person's OPEN (or PENDING)
# claims dated within a hold, and not bound by a statement, count in no live total. Responds with the person as stored.
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonHold
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { type Person } from '../people/people';
import { useGradeCodes } from '../grades/grades';
import { useSelectedPeople } from './selection';

type Result = { graded: number };

function SelectHead() {
  return <th>Select</th>;
}

/** The person's select checkbox: the selection a bulk action on people takes. */
function PersonSelect({ person }: { sheetId: string; user: string; person: Person }) {
  const [selected, setSelected] = useSelectedPeople();
  return (
    <td>
      <input
        type="checkbox"
        data-testid="person-select"
        checked={selected.includes(person.id)}
        onChange={(e) =>
          setSelected(e.target.checked ? [...selected, person.id] : selected.filter((id) => id !== person.id))
        }
      />
    </td>
  );
}

/** Gives the selected people a grade together, from a date (blank: the sheet's today): each, in list order, is edited
 *  exactly as the person form would. Shows how many were changed; the count is cleared while a new press runs. A refused
 *  bulk grade shows the error and changes nothing. */
function BulkGrade({ sheetId, user }: { sheetId: string; user: string }) {
  const gradeCodes = useGradeCodes(sheetId);
  const queryClient = useQueryClient();
  const [selected, setSelected] = useSelectedPeople();
  const [grade, setGrade] = useState<string>('A');
  const [from, setFrom] = useState('');
  const submit = useSubmitOnce();
  const apply = useMutation({
    mutationFn: (personIds: number[]) =>
      postJson<Result>(`/api/sheets/${encodeURIComponent(sheetId)}/bulk-grade`, {
        personIds,
        grade,
        from: from.trim(),
        by: user,
      }),
    onSuccess: async () => {
      setSelected([]);
      setFrom('');
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
    onSettled: submit.end,
  });

  return (
    <p data-testid="bulk-grade-bar">
      Grade selected people{' '}
      <select
        data-testid="bulk-grade"
        value={grade}
        onChange={(e) => {
          setGrade(e.target.value);
          apply.reset();
        }}
      >
        {gradeCodes.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>{' '}
      <label>
        From{' '}
        <input
          data-testid="bulk-grade-from"
          placeholder="yyyy-mm-dd"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            apply.reset();
          }}
        />
      </label>{' '}
      <button
        type="button"
        data-testid="bulk-grade-apply"
        disabled={apply.isPending}
        onClick={() => {
          if (!submit.begin()) return;
          apply.reset();
          apply.mutate(selected);
        }}
      >
        Give grade ({selected.length})
      </button>
      {apply.isSuccess && (
        <>
          {' '}
          Changed <span data-testid="bulk-graded">{apply.data.graded}</span>
        </>
      )}
      {apply.isError && <span data-testid="person-error"> Could not give the selected people the grade.</span>}
    </p>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 1, Component: SelectHead }),
  PersonRow.fill({ order: 1, Component: PersonSelect }),
  SheetPage.fill({ order: 11, Component: BulkGrade }),
];

